    remediation: 'A QR sign is a certification mark standing on real land: whoever walks past and scans it is shown a GACP page. Issuing a NEW sign for land whose certificate expired or was revoked is the platform marking uncertified ground as certified. Signs already issued are untouched — revoking one is a decision somebody makes (qrRevokedAt), not a side effect of an expiry date.',
