    source: 'services/billing/quotation-gate.js:167',
    remediation: 'validUntil is 7 working days from issue (config/business-rules.js PAYMENT.QUOTATION_VALIDITY_BUSINESS_DAYS, operator ruling re-confirmed 2026-09-27). An already-ACCEPTED quotation never expires; only a still-unaccepted one does. Raised at TWO doors on purpose (final round R1): the payment gate here, and the acceptance door (quotation-service.markQuotationAccepted). Without the second one the applicant cleared this refusal by pressing the accept button the same screen still drew. Where a replacement IS issued, the system does it, not staff: GET /api/applications/:id/quotations retires the lapsed row (status EXPIRED, soft-deleted with deleteReason EXPIRED_REISSUED) and issues a replacement carrying notes REISSUED_AFTER_EXPIRY:<old number>, audited as QUOTATION_REISSUED_AFTER_EXPIRY. That replacement window is quotation-issuance-on-submit.mayReplaceLapsedQuotation, which is WIDER than the mint window on purpose: SELF_HEAL_STATUSES, plus an M2-payable application whose lapsed row prices PHASE_2 only and has not been invoiced (the renewal, which reaches PENDING_AUDIT_FEE once its document check passes). Without that second half a renewal could never be replaced and never be paid. THREE shapes fall outside it and are replaced by nobody, which is why the Thai no longer promises a new document: (1) a pre-W14 DTAM+PLATFORM pair, refused by _lapsedOfferToReplace (live.length !== 1) because replacing a pair with one W14 document is a repricing decision, not a repair; (2) an M2-payable application whose lapsed row prices both instalments, or records none, whose replacement would re-bill a งวดที่ 1 already collected; (3) an M2-payable row whose phase2InvoicedAt is already stamped. Those three need the staff re-issue door the product does not have (ledger F-G4-71); until it exists the applicant is asked for the quotation number, which is what lets staff look at the row at all.',
