    messageEn: 'This report type no longer exists',
    messageTh: 'รายงานประเภทนี้เลิกใช้แล้ว กรุณาเลือกรายงานสรุปรายได้ประจำเดือนหรือรายงานภาษีขาย',
    source: 'services/financial-export-service.js:313',
    remediation: 'GET /api/invoices/export?type=gov_remittance asked for the DTAM remittance report, removed in PR2 of the DTAM remittance removal (operator 2026-09-29: DTAM is settled offline in the company\'s own accounts; the platform keeps no DTAM remittance). It used to fall through to the monthly revenue report, answering a different question under the same request. Use type=monthly or type=tax. No button in the web app asks for it.',
