    messageEn: 'The instalment named by the caller is not one this system prices',
    // The copy ended "เจ้าหน้าที่ได้รับแจ้งแล้ว" and nothing on this path tells
    // staff (review r1, finding 3): the close failure writes a logger.error line
    // and a QUOTATION_CLOSE_FAILED audit row, and an audit row is a record, not
    // an alert — no createNotification is raised anywhere here. The two
    // neighbouring rows that keep that sentence are backed by real notifications.
    // What is left is what is true, and it is the half that matters to the payer.
    messageTh: 'ระบบไม่สามารถปิดใบเสนอราคาของงวดนี้ได้ การชำระเงินและใบเสร็จของคุณยังคงอยู่ครบ',
